import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation, type GeospatialCamera } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.ts";

const R = 6371000;
function angleToDown(cam: GeospatialCamera): number {
    // angle between look direction and geocentric down at the centre
    const c = cam.center;
    const cl = Math.hypot(c.x, c.y, c.z);
    const up = { x: c.x / cl, y: c.y / cl, z: c.z / cl };
    const look = cam._lookAt;
    const d = -(look.x * up.x + look.y * up.y + look.z * up.z);
    return Math.acos(Math.max(-1, Math.min(1, d)));
}
function lookAtCentre(cam: GeospatialCamera): number {
    // angle between view direction (position->center) and _lookAt
    const dx = cam.center.x - cam.position.x, dy = cam.center.y - cam.position.y, dz = cam.center.z - cam.position.z;
    const l = Math.hypot(dx, dy, dz);
    const look = cam._lookAt;
    return Math.acos(Math.max(-1, Math.min(1, (dx * look.x + dy * look.y + dz * look.z) / l)));
}

describe("tiltGlobeCamera", () => {
    it("tilts a fresh (fully zoomed-out) camera and keeps zoom/heading/centre", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        const radius0 = cam.radius, yaw0 = cam.yaw, center0 = { ...cam.center };
        expect(radius0).toBeCloseTo(4 * R, 0);
        tiltGlobeCamera(cam, 0.6);
        expect(cam.pitch).toBeCloseTo(0.6, 9);
        expect(angleToDown(cam)).toBeCloseTo(0.6, 6);
        expect(lookAtCentre(cam)).toBeCloseTo(0, 6);
        expect(cam.radius).toBe(radius0);
        expect(cam.yaw).toBeCloseTo(yaw0, 9);
        expect(cam.center).toEqual(center0);
    });
    it("holds the tilt when zooming in and out and with nonzero yaw", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        setGeospatialOrientation(cam, { yaw: 1.1 });
        tiltGlobeCamera(cam, 1.2);
        for (const r of [4 * R, 3 * R, 2 * R, 1.5 * R, R * 1.05, 100, 10, 2 * R]) {
            cam.radius = r;
            expect(cam.pitch).toBeCloseTo(1.2, 9);
            expect(angleToDown(cam)).toBeCloseTo(1.2, 6);
            expect(lookAtCentre(cam)).toBeCloseTo(0, 6);
        }
        expect(cam.yaw).toBeCloseTo(1.1, 9);
    });
    it("works for a centre off the equator and a small tilt", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        cam.center = { x: 0, y: R * 0.6, z: R * 0.8 };
        tiltGlobeCamera(cam, 0.1);
        expect(cam.pitch).toBeCloseTo(0.1, 9);
        expect(lookAtCentre(cam)).toBeCloseTo(0, 6);
        cam.radius = 3 * R;
        expect(cam.pitch).toBeCloseTo(0.1, 9);
    });
});
EOF
